// ───────────────────────────── the starter-word invariant (batch 7) ─────────────────────────────

describe('every vocalized starter word of the Alphabet Sprint reads as itself (real shards; skipped when absent)', () => {
  const dir = new URL('../../public/lexicon/ar/standard/', import.meta.url);
  const have = fs.existsSync(new URL('manifest.json', dir));
  /** Words the SOURCE itself leaves ambiguous or files under another head; each with its reason. */
  const ALLOW: Record<string, string> = {};
  it.skipIf(!have)('(a) the vocalized word: its own lemma leads at 0.50 or more; (b) the bare key offers it; (c) ال + the bare key offers it (nouns and adjectives)', async () => {
    const zlib = await import('node:zlib');
    const { AR_CORE } = await import('../../src/adapters/arabic/generated/core');
    const { AR_PROFILE } = await import('../../packages/language-packs/src/alphabet-sprint/profiles/ar');
    const { arHeadForm, arCanon: canon } = await import('../../src/adapters/arabic/text');
    resetArabicIndexes();
    installArabicIndex(AR_CORE);
    for (const fn of fs.readdirSync(dir)) if (fn.endsWith('.json.gz')) installArabicIndex(JSON.parse(zlib.gunzipSync(fs.readFileSync(new URL(fn, dir))).toString('utf8')));
    useArIdentities({});
    useArPreferences();
    const heads = (w: string): Set<string> => new Set(['NOUN', 'VERB', 'ADJ', 'ADV', 'ADP', 'PRON', 'PART', 'CONJ', 'DET', 'PROPN'].map((p) => canon(arHeadForm(w, p))).concat(canon(w)));
    // compared without the last letter's vowel (a lemma head may carry a final vowel the printed citation form leaves bare)
    const endless = (x: string): string => canon(x).replace(/[\u064B-\u0650\u0652]+$/, '');
    const reads = (c: AnalysisCandidate, h: Set<string>): boolean => h.has(canon(c.lemma ?? '')) || [...h].some((x) => endless(x) === endless(c.lemma ?? '')) || (c.notes?.variants ? String(c.notes.variants).split(', ').some((v) => h.has(canon(v))) : false);
    const violations: string[] = [];
    let checked = 0;
    let undecided = 0;
    for (const w of AR_PROFILE.words) {
      const form = w.form.normalize('NFC');
      // a form that is not one fully vocalized word in its citation shape (unvocalized, or an inflected example with a tanwīn) is not a lemma form
      if (/\s/.test(form) || arKey(form).startsWith('ال') || ALLOW[form] || tashkilLevel(form) !== 'full' || /[\u064B-\u064D][^\u064B-\u0652]*$/.test(form)) continue;
      const h = heads(form);
      checked++;
      const a = cands(form);
      const top1 = a[0];
      if (a.some((c) => /(^|\s)\d+\.\s/.test(c.gloss ?? ''))) violations.push(`${form} (gloss) a numbered gloss`);
      { const gv = gapViolation(a); if (gv) violations.push(`${form} (gap) ${gv}`); }
      if (!top1 || !reads(top1, h)) { violations.push(`${form} (a) top ${top1?.lemma}|${top1?.pos} ${top1?.confidence}`); continue; }
      if (top1.confidence < 0.5) undecided++;
      if (!cands(arKey(form)).some((c) => reads(c, h))) violations.push(`${form} (b) bare key does not offer it`);
      if ((top1.pos === 'NOUN' || top1.pos === 'ADJ') && !cands(`ال${arKey(form)}`).some((c) => reads(c, h))) violations.push(`${form} (c) ال + key does not offer it`);
    }
    if (violations.length) console.log(`starter-word violations (${violations.length} of ${checked}):\n${violations.slice(0, 30).join('\n')}`);
    console.log(`starter words: ${checked} checked, ${undecided} read correctly but undecided`);
    expect(checked).toBeGreaterThan(150);
    // a fully vocalized lemma form is read as itself by the FIRST reading; a genuine pair of plain readings (a balanced entry of the reviewed list) may leave it undecided, but only a minority
    expect(undecided).toBeLessThan(checked * 0.15);
    expect(violations).toEqual([]);
    useArIdentities({});
    useArPreferences({});
    resetArabicIndexes();
    installArabicIndex(fixture);
  });
});

describe('batch 8 over the real index (skipped when the shards are absent)', () => {
  const dir = new URL('../../public/lexicon/ar/standard/', import.meta.url);
  const have = fs.existsSync(new URL('manifest.json', dir));
  it.skipIf(!have)('X1: the defective plural أَيْدٍ is not folded into the entry أَيْد; قَاضٍ, مَعَانٍ and the genitive كِتَابٍ are unaffected', async () => {
    const zlib = await import('node:zlib');
    const { AR_CORE } = await import('../../src/adapters/arabic/generated/core');
    resetArabicIndexes();
    installArabicIndex(AR_CORE);
    for (const fn of fs.readdirSync(dir)) if (fn.endsWith('.json.gz')) installArabicIndex(JSON.parse(zlib.gunzipSync(fs.readFileSync(new URL(fn, dir))).toString('utf8')));
    useArIdentities({});
    useArPreferences({});
    const a = cands('أَيْدٍ');
    expect(a.some((c) => c.lemma === 'يَد')).toBe(true);
    expect(a.some((c) => c.lemma === 'أَيْد' && c.confidence >= 0.5)).toBe(false);
    expect(top('قَاضٍ')).toMatchObject({ lemma: 'قَاضٍ' });
    expect(top('مَعَانٍ').lemma).toBe('مَعْنًى');
    expect(top('كِتَابٍ')).toMatchObject({ lemma: 'كِتَاب' });
    expect(top('كِتَابٍ').confidence).toBeGreaterThanOrEqual(0.5);
    // X2: an entry made of a conjunction and a closed-class word is one group with the chain; the chain is credited (list empty)
    for (const [w, lemma] of [['ولا', 'لَا'], ['ولكن', 'لٰكِنْ'], ['فلا', 'لَا'], ['وإن', 'إِنَّ']] as const) {
      const c = top(w);
      expect(c.lemma, w).toBe(lemma);
      expect(c.parts?.[0]?.kind, w).toBe('prefix');
      expect(c.confidence, w).toBeGreaterThanOrEqual(0.5);
    }
    expect(top('ولا').notes?.variants).toBe('وَلَا');
    resetArabicIndexes();
    installArabicIndex(fixture);
  });
});

describe('batch 9: the shards a word needs are the shards arLookupKeys asks for (real shards; skipped when absent)', () => {
  const dir = new URL('../../public/lexicon/ar/standard/', import.meta.url);
  const have = fs.existsSync(new URL('manifest.json', dir));
  const WORDS = ['الْمَدْرَسَةِ', 'الْكُتُبِ', 'الشَّمْسُ', 'الْقَمَرُ', 'وبالكتاب', 'فسيكتبونها', 'للبيت', 'ٱلْعَٰلَمِينَ', 'مدرسته', 'كتابه', 'الى', 'قارىء', 'الْيَوْمَ', 'الْيَوْمُ', 'للكتاب', 'للطالب', 'لله'];
  it.skipIf(!have)('core + ONLY the shards arLookupKeys names give the same candidates as every shard installed', async () => {
    const zlib = await import('node:zlib');
    const { AR_CORE } = await import('../../src/adapters/arabic/generated/core');
    const { arLookupKeys } = await import('../../src/adapters/arabic/shards');
    const { arShardLetters } = await import('../../src/adapters/arabic/text');
    const manifest = JSON.parse(fs.readFileSync(new URL('manifest.json', dir), 'utf8')) as { shards: Record<string, { file: string }> };
    const prefixes = Object.keys(manifest.shards).sort((a, b) => b.length - a.length);
    const load = (file: string): ArabicFormIndex => JSON.parse(zlib.gunzipSync(fs.readFileSync(new URL(file, dir))).toString('utf8'));
    const shardFor = (key: string): string | undefined => { const letters = arShardLetters(key); return prefixes.find((p) => letters.startsWith(p)); };
    const sig = (w: string): string => JSON.stringify(cands(w).map((c) => [c.lemma, c.pos, c.confidence, c.notes?.identity ?? '', (c.parts ?? []).map((p) => p.text).join('+')]));
    useArIdentities();
    useArPreferences();
    // every shard
    resetArabicIndexes();
    installArabicIndex(AR_CORE);
    for (const p of prefixes) installArabicIndex(load(manifest.shards[p].file));
    const full = new Map(WORDS.map((w) => [w, sig(w)] as const));
    const bad: string[] = [];
    for (const w of WORDS) {
      resetArabicIndexes();
      installArabicIndex(AR_CORE);
      const needed = new Set<string>();
      for (const k of arLookupKeys(w)) { const p = shardFor(k); if (p) needed.add(p); }
      for (const p of needed) installArabicIndex(load(manifest.shards[p].file));
      if (sig(w) !== full.get(w)) bad.push(w);
    }
    expect(bad).toEqual([]);
    useArIdentities({});
    useArPreferences({});
    resetArabicIndexes();
    installArabicIndex(fixture);
  });
  it('item 1: للبيت is لِ + ال + بيت (the lām of a verb stem beginning with ل is marginal); ليكتب (one lām) is unaffected', () => {
    // fixture: بَيْت is a noun; no verb لبيت is needed to state the structure of the rule, so check the cut shape only
    const c = top('للبيت');
    expect(c).toMatchObject({ lemma: 'بَيْت' });
    expect(partTexts(c)).toEqual(['ل', 'ل', 'بيت']);
  });
});

describe('batch 10: the demonstratives, relatives and pronouns are words of their own', () => {
  const OWN: Array<[string, string]> = [
    ['هٰذَا', 'هٰذَا'], ['هٰذِهِ', 'هٰذِهِ'], ['هٰذَانِ', 'هٰذَانِ'], ['هٰذَيْنِ', 'هٰذَيْنِ'], ['هَاتَانِ', 'هَاتَانِ'], ['هَاتَيْنِ', 'هَاتَيْنِ'], ['هٰؤُلَاءِ', 'هٰؤُلَاءِ'],
    ['ذٰلِكَ', 'ذٰلِكَ'], ['تِلْكَ', 'تِلْكَ'], ['ذَانِكَ', 'ذَانِكَ'], ['أُولٰئِكَ', 'أُولٰئِكَ'], ['ذَاكَ', 'ذَاكَ'],
    ['الَّذِي', 'الَّذِي'], ['الَّتِي', 'الَّتِي'], ['اللَّذَانِ', 'اللَّذَانِ'], ['اللَّذَيْنِ', 'اللَّذَيْنِ'], ['اللَّتَانِ', 'اللَّتَانِ'], ['اللَّتَيْنِ', 'اللَّتَيْنِ'],
    ['الَّذِينَ', 'الَّذِينَ'], ['اللَّاتِي', 'اللَّاتِي'], ['اللَّوَاتِي', 'اللَّوَاتِي'], ['اللَّائِي', 'اللَّائِي'],
    ['هُوَ', 'هُوَ'], ['هِيَ', 'هِيَ'], ['هُمَا', 'هُمَا'], ['هُمْ', 'هُمْ'], ['هُنَّ', 'هُنَّ'], ['أَنْتَ', 'أَنْتَ'], ['أَنْتِ', 'أَنْتِ'], ['أَنْتُمَا', 'أَنْتُمَا'], ['أَنْتُمْ', 'أَنْتُمْ'], ['أَنْتُنَّ', 'أَنْتُنَّ'], ['أَنَا', 'أَنَا'], ['نَحْنُ', 'نَحْنُ'],
  ];
  const same = (a: string | undefined, b: string): boolean => (a ?? '') === b || arKey(a ?? '') === arKey(b) && a?.normalize('NFC').replace(/[َٰ]/g, '') === b.normalize('NFC').replace(/[َٰ]/g, '');
  it('each reads as its OWN lemma (not as a form of the masculine singular), vocalized and unvocalized, with the reviewed list overridden', () => {
    useArIdentities({});
    const bad: string[] = [];
    for (const [form, lemma] of OWN) {
      for (const w of [form, arKey(form)]) {
        const c = top(w);
        // unvocalized, a spelling shared by two words (أَنْتَ / أَنْتِ) may lead with either
        const ok = w === form ? same(c?.lemma, lemma) : arKey(c?.lemma ?? '') === arKey(lemma);
        if (!ok || c.pos !== 'PRON') bad.push(`${w} -> ${c?.lemma}|${c?.pos}`);
      }
    }
    expect(bad).toEqual([]);
  });
  it('behind و / ف (and ب / ل for the demonstratives) they keep their own lemma and the conjunction or preposition is a prefix part', () => {
    useArIdentities({});
    const bad: string[] = [];
    for (const [form, lemma] of OWN.filter(([f]) => !/^ال/.test(f))) {
      for (const p of ['و', 'ف']) {
        const c = top(p + arKey(form));
        if (!c || arKey(c.lemma ?? '') !== arKey(lemma) || c.parts?.[0]?.kind !== 'prefix') bad.push(`${p}${arKey(form)} -> ${c?.lemma}`);
      }
    }
    for (const [form, lemma] of [['هٰذِهِ', 'هٰذِهِ'], ['ذٰلِكَ', 'ذٰلِكَ'], ['تِلْكَ', 'تِلْكَ']]) for (const p of ['ب', 'ل']) { const c = top(p + arKey(form)); if (!c || !same(c.lemma, lemma)) bad.push(`${p}${arKey(form)} -> ${c?.lemma}`); }
    expect(bad).toEqual([]);
  });
  it('the index\'s reading of the feminine as a form of the masculine word is named in notes.variants, not credited', () => {
    useArIdentities({});
    const c = top('تلك');
    expect(c.lemma).toBe('تِلْكَ');
    expect(c.notes?.variants === undefined || c.notes.variants === 'ذٰلِكَ').toBe(true);
    expect(cands('تلك').some((x) => x.lemma === 'ذٰلِكَ')).toBe(false);
  });
});
